"""Map Coval simulations back to voice run manifest entries."""

from __future__ import annotations

from collections import defaultdict
from typing import Any, Dict, List, Mapping, Sequence

from rasa.builder.copilot.mcp_server.tools.coval.manifest import VoiceRunManifestEntry


class CorrelationError(ValueError):
    """Raised when a simulation cannot be matched to exactly one manifest entry."""


def correlate_simulations_to_manifest(
    simulations: Sequence[Mapping[str, Any]],
    manifest: Sequence[VoiceRunManifestEntry],
) -> Dict[str, VoiceRunManifestEntry]:
    """Return ``simulation_id`` → manifest entry for a Coval run.

    Matches on ``simulation["test_case_id"]``. Raises when a simulation has no
    matching manifest entry, or when multiple manifest entries share the same
    ``test_case_id`` (ambiguous for multi-iteration runs in a single Coval run).
    """
    by_test_case: Dict[str, List[VoiceRunManifestEntry]] = defaultdict(list)
    for entry in manifest:
        by_test_case[entry.test_case_id].append(entry)

    ambiguous_test_cases = {
        test_case_id
        for test_case_id, entries in by_test_case.items()
        if len(entries) > 1
    }
    if ambiguous_test_cases and len(simulations) > 1:
        raise CorrelationError(
            "manifest has multiple entries for test_case_id(s) "
            f"{sorted(ambiguous_test_cases)}; cannot correlate a multi-simulation "
            "run without per-iteration identity from Coval"
        )

    result: Dict[str, VoiceRunManifestEntry] = {}
    for simulation in simulations:
        simulation_id = simulation.get("simulation_id")
        if not simulation_id:
            raise CorrelationError("simulation missing simulation_id")

        test_case_id = simulation.get("test_case_id")
        if not test_case_id:
            raise CorrelationError(f"simulation {simulation_id!r} missing test_case_id")

        candidates = by_test_case.get(str(test_case_id), [])
        if not candidates:
            raise CorrelationError(
                f"no manifest entry for test_case_id={test_case_id!r} "
                f"(simulation {simulation_id})"
            )
        if len(candidates) > 1:
            raise CorrelationError(
                f"ambiguous manifest match for test_case_id={test_case_id!r} "
                f"(simulation {simulation_id})"
            )

        result[str(simulation_id)] = candidates[0]

    return result
